# Generated by test-lab — blind adversarial evaluation
"""Selection must act on the probe's verdict, not only on rate limiting (#1397).

A Battle agentic-evals run asked for `--handler webgpt`. The probe reported
`provider_limited: false` but `probe_degraded: true` with
`browser_provider_probe_timeout`, and selection consulted only
`provider_limited` — so webgpt stayed active, Tau dispatched into a provider
whose state was unknown, no handler artifacts were ever written, and the caller
waited until it was killed by hand.
"""

from __future__ import annotations

import sys
from pathlib import Path
from types import SimpleNamespace

import pytest

SKILL_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(SKILL_ROOT / "src"))

from ask.tau_dag_cli import (  # noqa: E402
    _select_available_browser_handlers,
    browser_provider_selection_blocked_execution,
)


def _report(**providers: dict) -> dict:
    return {"live": True, "providers": providers}


def _degraded(code: str = "browser_provider_probe_timeout", auto_retry: bool = False) -> dict:
    """The exact shape the probe wrote for webgpt in the #1397 run."""
    return {
        "provider_limited": False,
        "probe_failed": False,
        "probe_degraded": True,
        "failure_code": code,
        "provider_probe_recovery_packet": {
            "auto_retry_allowed": auto_retry,
            "auto_retry_blocked_reason": "provider_probe_uncertain_requires_readback",
        },
    }


def _healthy() -> dict:
    return {"provider_limited": False, "probe_failed": False, "probe_degraded": False}


def _payload(handlers: list[str], template: str = "single-call") -> SimpleNamespace:
    return SimpleNamespace(
        handlers=handlers, workflow_mode="", dag_template=template, request="battle evals"
    )


def test_a_degraded_provider_is_not_dispatched_into() -> None:
    selection = _select_available_browser_handlers(
        _payload(["webgpt"]), _report(webgpt=_degraded())
    )
    assert selection["removed_handlers"] == ["webgpt"]
    assert selection["status"] == "BLOCKED"


def test_the_caller_gets_a_terminal_artifact_instead_of_waiting() -> None:
    """The whole point of #1397: never leave the caller with no artifacts."""
    selection = _select_available_browser_handlers(
        _payload(["webgpt"]), _report(webgpt=_degraded())
    )
    execution = browser_provider_selection_blocked_execution(selection)
    assert execution["ok"] is False
    assert execution["status"] == "NEEDS_ATTENTION"
    assert execution["no_tau_execution"] is True


def test_the_reported_cause_is_the_real_one() -> None:
    """failure_code was hardcoded to rate-limited, mislabelling every removal."""
    selection = _select_available_browser_handlers(
        _payload(["webgpt"]), _report(webgpt=_degraded())
    )
    assert selection["failure_code"] == "browser_provider_probe_timeout"
    assert selection["unusable_providers"] == {"webgpt": "browser_provider_probe_timeout"}


def test_a_failed_probe_is_also_removed() -> None:
    provider = {"provider_limited": False, "probe_failed": True, "failure_code": "boom"}
    selection = _select_available_browser_handlers(
        _payload(["webgpt"]), _report(webgpt=provider)
    )
    assert selection["removed_handlers"] == ["webgpt"]
    assert selection["failure_code"] == "boom"


def test_degraded_but_retryable_still_runs() -> None:
    """Uncertainty alone does not block; the packet forbidding retry does.

    Removing every degraded provider would ground the panel on transient noise.
    """
    selection = _select_available_browser_handlers(
        _payload(["webgpt"]), _report(webgpt=_degraded(auto_retry=True))
    )
    assert selection["removed_handlers"] == []
    assert selection["status"] == "READY"


def test_an_explicit_single_seat_is_never_answered_by_another_provider() -> None:
    """--handler webgpt must not silently return webclaude's answer."""
    selection = _select_available_browser_handlers(
        _payload(["webgpt"]), _report(webgpt=_degraded(), webclaude=_healthy())
    )
    assert selection["active_handlers"] == []
    assert selection["fallback_handlers"] == []
    assert selection["status"] == "BLOCKED"


def test_fresh_single_seat_survives_ambient_probe_timeout() -> None:
    """Old-tab probe timeouts must not prevent Ask from creating a fresh tab."""
    selection = _select_available_browser_handlers(
        _payload(["webgpt"]),
        _report(webgpt=_degraded("browser_provider_probe_timeout")),
        browser_tab_lifecycle="fresh-keep",
    )
    assert selection["status"] == "READY"
    assert selection["active_handlers"] == ["webgpt"]
    assert selection["removed_handlers"] == []
    assert selection["fresh_lifecycle_kept_handlers"] == ["webgpt"]
    assert selection["unusable_providers"] == {"webgpt": "browser_provider_probe_timeout"}


def test_fresh_single_seat_still_blocks_on_non_timeout_degraded_probe() -> None:
    """Fresh-tab keep is only for old-tab cooldowns and old-tab read timeouts."""
    selection = _select_available_browser_handlers(
        _payload(["webgpt"]),
        _report(webgpt=_degraded("browser_provider_auth_unknown")),
        browser_tab_lifecycle="fresh-keep",
    )
    assert selection["status"] == "BLOCKED"
    assert selection["active_handlers"] == []
    assert selection["removed_handlers"] == ["webgpt"]
    assert selection["fresh_lifecycle_kept_handlers"] == []


def test_a_roundtable_still_falls_back_to_healthy_seats() -> None:
    """Multi-seat panels keep substituting; seats there are interchangeable."""
    selection = _select_available_browser_handlers(
        _payload(["webgpt", "webclaude"], template="roundtable"),
        _report(webgpt=_degraded(), webclaude=_healthy(), webgrok=_healthy()),
    )
    assert "webgpt" in selection["removed_handlers"]
    assert "webclaude" in selection["active_handlers"]
    assert selection["status"] == "ADJUSTED"


def test_a_healthy_provider_is_untouched() -> None:
    selection = _select_available_browser_handlers(
        _payload(["webgpt"]), _report(webgpt=_healthy())
    )
    assert selection["status"] == "READY"
    assert selection["removed_handlers"] == []


@pytest.mark.parametrize("packet", [None, {}, "not-a-dict"])
def test_a_degraded_provider_without_a_usable_packet_still_runs(packet: object) -> None:
    """Absent guidance is not permission to block; only an explicit refusal is."""
    provider = {"provider_limited": False, "probe_degraded": True, "provider_probe_recovery_packet": packet}
    selection = _select_available_browser_handlers(
        _payload(["webgpt"]), _report(webgpt=provider)
    )
    assert selection["removed_handlers"] == []
